// Some portions generated by Claude
import { useCallback, useEffect, useMemo, useRef, useState, type Dispatch, type SetStateAction } from "react";
import { FACET_LIST_LIMIT } from "./explorer-config.ts";
import type { FilterFacet, RangeDraft } from "./explorer-types.ts";
import { formatRangeValue, generatedFacetQuery, type QueryRange } from "./facet-queries.ts";
import {
  facetCounts,
  facetIndex,
  RANGE_VALUE,
  toggleTypeInSelection,
  type RepositoryValues,
} from "./graph-facets.ts";
import type { GraphEdge, GraphNode } from "./graph-types.ts";
import {
  BLANK_VISUAL,
  facetValueVisual,
  LITERAL_VISUAL,
  LOADING_IRI_VISUAL,
  nodeTypeIds,
  nodeVisual,
  TYPE_PALETTE,
  typeVisual,
  UNTYPED_IRI_TYPE,
} from "./graph-visuals.ts";

export type FilterChip = { facetId: string; valueId: string | null; text: string };

export type DisplayedFacet = FilterFacet & { searchHit: boolean };

export type FacetFilters = ReturnType<typeof useFacetFilters>;

/** The repository's values for the filtered nodes (use-repository-facets.ts). */
export type FacetRepository = {
  valuesOf: RepositoryValues;
  labelOf: (id: string) => string | undefined;
  /** Moves whenever values or labels arrive. */
  version: number;
  /** Which of the nodes have a selected value, or one inside the range, for the predicate, asked of the repository. */
  confirm: (
    predicate: string,
    ids: readonly string[],
    match: { values: string[] } | { range: QueryRange },
    signal: AbortSignal,
  ) => Promise<Set<string>>;
  wantLabels: (iris: readonly string[], priority: "shown" | "background") => void;
};

/** Values each listed filter shows before "Show more": their labels are asked for first. */
const SHOWN_VALUES = 12;
const EMPTY_MATCHES = new Set<string>();

/**
 * The state of the Filters panel and everything derived from it: the filter model over the selectable nodes (their
 * loaded links and, through `repository`, every value the repository has for them), the facets as the panel lists
 * them (search, "more filters"), the active filters as chips, the generated SPARQL of the selection, and the actions
 * the panel and the rest of the explorer use to change it.
 */
export function useFacetFilters(input: {
  /** The selected values per filter; owned by the explorer because undo and storage include it. */
  selection: Map<string, Set<string>>;
  setSelection: Dispatch<SetStateAction<Map<string, Set<string>>>>;
  nodes: readonly GraphNode[];
  edges: readonly GraphEdge[];
  nodeById: ReadonlyMap<string, GraphNode>;
  hiddenPredicates: ReadonlySet<string>;
  /** Called whenever a filter changes, so a hand-made selection gives way to the filters. */
  onChange: () => void;
  /**
   * Whether anything needs the filter model: the panel is open or a filter is active. On a large graph the model
   * costs a pass over every node and edge, so it is not kept up to date while nobody looks at it.
   */
  needed: boolean;
  scope?: string;
  repository?: FacetRepository;
}) {
  const { selection, setSelection, nodes, edges, nodeById, hiddenPredicates, onChange, needed, repository } = input;
  // Filters the user opened or closed by hand; the others follow the defaults of the panel.
  const [facetOpen, setFacetOpen] = useState<Map<string, boolean>>(() => new Map());
  const [showAll, setShowAll] = useState(false);
  const [search, setSearch] = useState("");
  // The typed bounds of range filters; they apply while the filter is part of the selection.
  const [rangeDrafts, setRangeDrafts] = useState<Map<string, RangeDraft>>(() => new Map());
  // Nodes the repository confirmed for a filter whose values were not all loaded for them, per selection.
  const [confirmed, setConfirmed] = useState<Map<string, { key: string; ids: Set<string> }>>(() => new Map());

  const repositoryValues = repository?.valuesOf;
  const labelOf = repository?.labelOf;
  const repositoryVersion = repository?.version ?? 0;
  // Built once per change of the data (or of the values and labels that arrived); counting per selection is cheap.
  const index = useMemo(
    () => {
      void repositoryVersion;
      return facetIndex({
        nodes: needed ? nodes : [],
        edges: needed ? edges : [],
        nodeById,
        typesOf: (node) =>
          nodeTypeIds(node).map((typeId) => node.types?.find((type) => type.id === typeId) ?? UNTYPED_IRI_TYPE),
        hiddenPredicates,
        repositoryValues,
        labelOf,
      });
    },
    [edges, hiddenPredicates, nodeById, nodes, needed, repositoryValues, labelOf, repositoryVersion],
  );
  // A range filter selects RANGE_VALUE; its bounds are the texts typed into it.
  const rangeBounds = useMemo(
    () => new Map([...rangeDrafts].filter(([facetId]) => selection.get(facetId)?.has(RANGE_VALUE))),
    [rangeDrafts, selection],
  );
  const confirmedIds = useMemo(
    () => new Map([...confirmed].map(([facetId, entry]) => [facetId, entry.ids] as const)),
    [confirmed],
  );
  const model = useMemo(
    () => facetCounts(index, selection, { ranges: rangeBounds, confirmed: confirmedIds }),
    [index, selection, rangeBounds, confirmedIds],
  );

  // A filter on a predicate some nodes have more values for than were loaded: the repository says which of them match.
  useEffect(() => {
    if (!repository) return;
    const controller = new AbortController();
    const wanted = new Map<string, { key: string; ids: string[]; match: { values: string[] } | { range: QueryRange } }>();
    selection.forEach((values, facetId) => {
      const incomplete = index.incomplete.get(facetId);
      if (!values.size || !incomplete?.size) return;
      const bounds = rangeBounds.get(facetId);
      const range = index.ranges.get(facetId);
      const match = values.has(RANGE_VALUE) && bounds && range
        ? { range: { kind: range.kind, from: bounds.from, to: bounds.to } }
        : { values: [...values].filter((value) => value !== RANGE_VALUE) };
      const ids = [...incomplete].sort();
      wanted.set(facetId, { key: JSON.stringify([ids, match]), ids, match });
    });
    setConfirmed((current) => {
      const kept = new Map([...current].filter(([facetId, entry]) => wanted.get(facetId)?.key === entry.key));
      return kept.size === current.size ? current : kept;
    });
    wanted.forEach(({ key, ids, match }, facetId) => {
      if (confirmed.get(facetId)?.key === key) return;
      repository
        .confirm(facetId, ids, match, controller.signal)
        .then((matched) => {
          if (!controller.signal.aborted) setConfirmed((current) => new Map(current).set(facetId, { key, ids: matched }));
        })
        .catch(() => undefined);
    });
    return () => controller.abort();
    // `confirmed` is read to skip settled checks, not to start new ones.
  }, [index, selection, rangeBounds, repository?.confirm]);

  const facets = useMemo<FilterFacet[]>(
    () =>
      model.facets.map((facet) => {
        const values = facet.values.map((value) => ({
          ...value,
          visual:
            facet.category === "type"
              ? typeVisual(value.id)
              : facet.category === "kind"
                ? value.id === "literal"
                  ? LITERAL_VISUAL
                  : value.id === "blank"
                    ? BLANK_VISUAL
                    : TYPE_PALETTE[0]
                : facet.category === "predicate"
                  ? value.node
                    ? nodeVisual(value.node)
                    : value.kind === "literal"
                      ? LITERAL_VISUAL
                      : value.kind === "blank"
                        ? BLANK_VISUAL
                        : LOADING_IRI_VISUAL
                  : facetValueVisual(`${facet.category}:${value.id}`),
        }));
        return {
          ...facet,
          values,
          maxCount: values.reduce((max, value) => Math.max(max, value.count), 1),
        };
      }),
    [model.facets],
  );

  const activeCount = useMemo(() => [...selection.values()].filter((values) => values.size > 0).length, [selection]);
  // The same set while its members stay the same: the canvas repaints its selection only when it changes.
  const previousMatches = useRef<Set<string>>(EMPTY_MATCHES);
  const matches = useMemo(() => {
    if (!activeCount) return EMPTY_MATCHES;
    const previous = previousMatches.current;
    const next = model.matches;
    if (previous.size === next.size && [...next].every((id) => previous.has(id))) return previous;
    previousMatches.current = next;
    return next;
  }, [activeCount, model.matches]);

  const generatedQuery = useMemo(
    () =>
      generatedFacetQuery(selection, {
        wikidata: false,
        scope: input.scope,
        ranges: new Map(
          facets.flatMap((facet) => {
            const draft = rangeDrafts.get(facet.id);
            return facet.range && draft && selection.has(facet.id)
              ? [[facet.id, { kind: facet.range.kind, ...draft }] as const]
              : [];
          }),
        ),
      }),
    [facets, rangeDrafts, selection, input.scope],
  );

  const displayed = useMemo<DisplayedFacet[]>(() => {
    const term = search.trim().toLocaleLowerCase();
    return facets.flatMap((facet) => {
      const values = facet.values;
      const nameMatches = !term || facet.label.toLocaleLowerCase().includes(term);
      const shown = nameMatches ? values : values.filter((value) => value.label.toLocaleLowerCase().includes(term));
      if (!nameMatches && !shown.length) return [];
      return [
        {
          ...facet,
          values: shown,
          searchHit: Boolean(term) && !nameMatches,
          maxCount: values.reduce((max, value) => Math.max(max, value.count), 1),
        },
      ];
    });
  }, [facets, search]);

  const listed = useMemo(
    () =>
      showAll || search.trim()
        ? displayed
        : displayed.filter((facet, index) => index < FACET_LIST_LIMIT || selection.has(facet.id)),
    [displayed, search, selection, showAll],
  );

  const chips = useMemo(
    () =>
      facets.flatMap((facet): FilterChip[] => {
        const selected = selection.get(facet.id);
        if (!selected?.size) return [];
        const draft = rangeDrafts.get(facet.id);
        if (facet.range && draft) {
          const bound = (text: string, fallback: number) => text.trim() || formatRangeValue(facet.range!.kind, fallback);
          return [
            {
              facetId: facet.id,
              valueId: null,
              text: `${facet.label}: ${bound(draft.from, facet.range.min)} – ${bound(draft.to, facet.range.max)}`,
            },
          ];
        }
        return facet.values
          .filter((value) => selected.has(value.id))
          .map((value) => ({
            facetId: facet.id,
            valueId: value.id,
            text: facet.category === "type" ? value.label : `${facet.label}: ${value.label}`,
          }));
      }),
    [facets, rangeDrafts, selection],
  );

  const clear = useCallback(() => setSelection((current) => (current.size ? new Map() : current)), [setSelection]);

  const toggleValue = useCallback(
    (facetId: string, valueId: string, checked: boolean) => {
      setSelection((current) => {
        const next = new Map(current);
        const values = new Set(next.get(facetId) ?? []);
        if (checked) values.add(valueId);
        else values.delete(valueId);
        if (values.size) next.set(facetId, values);
        else next.delete(facetId);
        return next;
      });
      onChange();
    },
    [onChange, setSelection],
  );

  /** Removes one value of a filter, or the whole filter when `valueId` is null (a range). */
  const removeValue = useCallback(
    (facetId: string, valueId: string | null) => {
      if (valueId !== null) {
        toggleValue(facetId, valueId, false);
        return;
      }
      setSelection((current) => {
        const next = new Map(current);
        next.delete(facetId);
        return next;
      });
      onChange();
    },
    [onChange, setSelection, toggleValue],
  );

  const updateRange = useCallback(
    (facet: FilterFacet, bound: keyof RangeDraft, text: string) => {
      const current = selection.has(facet.id) ? rangeDrafts.get(facet.id) : undefined;
      const draft = { from: current?.from ?? "", to: current?.to ?? "", [bound]: text };
      setRangeDrafts((drafts) => new Map(drafts).set(facet.id, draft));
      // The selection names the range, not its values: they are matched by value (graph-facets.ts, RANGE_VALUE).
      setSelection((previous) => {
        const next = new Map(previous);
        if (draft.from.trim() || draft.to.trim()) next.set(facet.id, new Set([RANGE_VALUE]));
        else next.delete(facet.id);
        return next;
      });
      onChange();
    },
    [onChange, rangeDrafts, selection, setSelection],
  );

  /** A legend chip: its type joins the type filter or leaves it; other filters stay (see toggleTypeInSelection). */
  const toggleType = useCallback(
    (facetId: string, typeId: string) => {
      setSelection((current) => toggleTypeInSelection(current, facetId, typeId));
      onChange();
    },
    [onChange, setSelection],
  );

  const isTypeSelected = useCallback(
    (facetId: string, typeId: string) => Boolean(selection.get(facetId)?.has(typeId)),
    [selection],
  );

  /** Undo and Redo put the range texts back with the filters they belong to. */
  const restoreRangeDrafts = useCallback((drafts: ReadonlyMap<string, RangeDraft>) => setRangeDrafts(new Map(drafts)), []);

  // Labels for the IRI values: those the panel shows first, then the rest in the background.
  const wantLabels = repository?.wantLabels;
  useEffect(() => {
    if (!wantLabels || !needed) return;
    const shown: string[] = [];
    const rest: string[] = [];
    listed.forEach((facet) => {
      if (facet.category !== "predicate") return;
      if (!facet.values.length) shown.push(facet.id);
      facet.values.forEach((value, position) => {
        if (value.kind !== "iri") return;
        (position < SHOWN_VALUES ? shown : rest).push(value.id);
      });
    });
    facets.forEach((facet) => {
      if (facet.category === "predicate") shown.push(facet.id);
    });
    wantLabels(shown, "shown");
    wantLabels(rest, "background");
  }, [facets, listed, needed, wantLabels]);

  return {
    selection,
    setSelection,
    facetOpen,
    setFacetOpen,
    showAll,
    setShowAll,
    search,
    setSearch,
    rangeDrafts,
    model,
    index,
    facets,
    displayed,
    listed,
    chips,
    activeCount,
    hasActive: activeCount > 0,
    matches,
    generatedQuery,
    clear,
    toggleValue,
    removeValue,
    updateRange,
    toggleType,
    isTypeSelected,
    restoreRangeDrafts,
  };
}
